const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
let token=localStorage.getItem('fenix_token')||'',me=null,chats=[],active=null,messages=[],ws=null,mode='chats',query='',picker='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>(s||'F').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const avatar=u=>u?.avatar?`<img src="${esc(u.avatar)}" alt="">`:esc(initials(u?.display_name||u?.title||'F'));
const t=s=>{try{return new Date(s).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}catch{return''}};
async function req(path,opt={}){const h={...(opt.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opt.headers||{})};if(token)h.Authorization='Bearer '+token;const r=await fetch(path,{...opt,headers:h});let d={};const text=await r.text();try{d=text?JSON.parse(text):{}}catch{d={detail:text}}if(r.status===401&&!path.includes('/auth/login')&&!path.includes('/auth/register')){localStorage.removeItem('fenix_token');token='';me=null;render();throw Error('Сессия недействительна. Войдите снова.')}if(!r.ok){let x=d.detail;if(Array.isArray(x))x=x.map(v=>v.msg||v.message||String(v)).join('; ');throw Error(x||'Ошибка запроса')}return d}
function toast(x){const e=document.createElement('div');e.className='toast';e.textContent=x;document.body.append(e);setTimeout(()=>e.remove(),3000)}
function modal(html){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal">${html}</div></div>`);$('#modal').onclick=e=>{if(e.target.id==='modal')e.currentTarget.remove()}}
function render(){document.body.classList.toggle('dark',localStorage.getItem('fenix_theme')==='dark');token?renderApp():renderAuth()}
function renderAuth(){document.getElementById('app').innerHTML=`<div class="auth-page"><form class="auth-card" id="auth"><div class="brand-logo">F</div><h1>Fenix Messenger</h1><p id="authhint">Общайтесь без границ</p><label>Юзернейм</label><input id="u" minlength="5" maxlength="32" pattern="[A-Za-z0-9_]+" placeholder="минимум 5 символов" required><div id="namebox" class="hidden"><label>Имя</label><input id="n" maxlength="80" placeholder="Ваше имя"></div><label>Пароль</label><input id="p" type="password" minlength="6" required placeholder="минимум 6 символов"><button class="primary" id="submit">Войти</button><button type="button" class="linkbtn" id="switch">Нет аккаунта? Зарегистрироваться</button></form></div>`;let reg=false;$('#switch').onclick=()=>{reg=!reg;$('#namebox').classList.toggle('hidden',!reg);$('#authhint').textContent=reg?'Создайте аккаунт — юзернейм от 5 символов':'Общайтесь без границ';$('#submit').textContent=reg?'Создать аккаунт':'Войти';$('#switch').textContent=reg?'Уже есть аккаунт? Войти':'Нет аккаунта? Зарегистрироваться'};$('#auth').onsubmit=async e=>{e.preventDefault();const u=$('#u').value.trim().toLowerCase(),p=$('#p').value,n=$('#n')?.value.trim()||'';if(u.length<5)return toast('Юзернейм — минимум 5 символов');if(!/^[a-z0-9_]+$/.test(u))return toast('Юзернейм: только латиница, цифры и _');if(p.length<6)return toast('Пароль — минимум 6 символов');if(reg&&!n)return toast('Введите имя');const b=reg?{username:u,display_name:n,password:p}:{username:u,password:p};try{const d=await req(reg?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(b)});token=d.access_token;localStorage.setItem('fenix_token',token);await boot()}catch(x){toast(x.message)}}}
async function boot(){try{me=await req('/api/auth/me');chats=await req('/api/chats');render()}catch(e){token='';localStorage.removeItem('fenix_token');render();toast(e.message)}}
function renderApp(){document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><header><div class="brand"><div class="brand-logo sm">F</div><b>Fenix</b></div><div class="head-actions"><button class="icon" id="newchat">＋</button><button class="icon" id="mebtn">⚙</button></div></header><div class="searchbar"><span>⌕</span><input id="search" value="${esc(query)}" placeholder="Поиск по @username, ID или имени"></div><nav class="nav"><button data-mode="chats">💬 Чаты</button><button data-mode="people">👥 Люди</button><button data-mode="saved">⭐ Избранное</button><button data-mode="search">🔎 Поиск</button></nav><div id="list" class="list"></div><div class="mybar" id="mybar"><div class="avatar">${avatar(me)}</div><div><b>${esc(me.display_name)}</b><small>@${esc(me.username)}${me.public_code?' · ID '+esc(me.public_code):''}</small></div></div></aside><main class="main" id="main"></main></div>`;$$('.nav button').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;loadList()});$('#search').oninput=e=>{query=e.target.value;clearTimeout(window.st);window.st=setTimeout(loadList,250)};$('#mebtn').onclick=profile;$('#mybar').onclick=profile;$('#newchat').onclick=()=>newChat();loadList();drawMain()}
async function loadList(){const list=$('#list');if(!list)return;try{if(mode==='people'){const q=query.trim();if(q&&q.length<5)return list.innerHTML='<div class="hint">Для поиска человека введите минимум 5 символов юзернейма или 3/4-значный ID.</div>';const us=await req('/api/users?q='+encodeURIComponent(q));list.innerHTML=us.map(u=>`<button class="person" data-id="${u.id}"><div class="avatar">${avatar(u)}${u.online?'<i/>':''}</div><div><b>${esc(u.display_name)}</b><small>@${esc(u.username)} ${u.public_code?'· ID '+esc(u.public_code):''}</small></div></button>`).join('')||'<div class="hint">Никого не найдено</div>';$$('.person').forEach(x=>x.onclick=async()=>{const c=await req('/api/chats/private',{method:'POST',body:JSON.stringify({other_user_id:+x.dataset.id})});active=c;mode='chats';chats=await req('/api/chats');drawMain();loadList()});return}if(mode==='saved'){const fs=await req('/api/extras/favorites');list.innerHTML=fs.map(f=>`<button class="savedrow" data-chat="${f.chat_id}"><span>⭐</span><div><b>${esc(f.text||'Медиа')}</b><small>${t(f.created_at)}</small></div></button>`).join('')||'<div class="hint">Избранное пусто. Нажмите ⭐ у сообщения.</div>';$$('.savedrow').forEach(x=>x.onclick=()=>{const c=chats.find(c=>c.id===+x.dataset.chat);if(c){active=c;drawMain()}});return}if(mode==='search'){if(!query.trim())return list.innerHTML='<div class="hint">Введите текст сообщения.</div>';const ms=await req('/api/search/messages?q='+encodeURIComponent(query));list.innerHTML=ms.map(m=>`<div class="result"><b>Сообщение #${m.id}</b><span>${esc(m.text||'Медиа')}</span></div>`).join('')||'<div class="hint">Ничего не найдено</div>';return}chats=await req('/api/chats');list.innerHTML=chats.map(c=>`<button class="chatrow ${active?.id===c.id?'active':''}" data-id="${c.id}"><div class="avatar">${c.avatar?`<img src="${esc(c.avatar)}">`:esc(initials(c.title))}</div><div><div class="line"><b>${esc(c.title)}</b><small>${c.kind==='group'?'Группа':''}</small></div><span>${esc(c.description||'Начать общение')}</span></div></button>`).join('')||'<div class="hint">Чатов пока нет.<br>Найдите человека во вкладке «Люди».</div>';$$('.chatrow').forEach(x=>x.onclick=()=>{active=chats.find(c=>c.id===+x.dataset.id);drawMain();loadList()})}catch(e){toast(e.message)}}
function drawMain(){const m=$('#main');if(!m)return;if(!active){m.innerHTML=`<div class="welcome"><div class="welcome-logo">F</div><h2>Fenix Messenger</h2><p>Найдите человека по <b>@username</b> или 3/4-значному ID и начните общение.</p></div>`;return}m.innerHTML=`<section class="chat"><header class="chathead"><button class="icon back" onclick="active=null;drawMain();loadList()">‹</button><div class="avatar">${active.avatar?`<img src="${esc(active.avatar)}">`:esc(initials(active.title))}</div><div class="chat-title"><b>${esc(active.title)}</b><small>${active.kind==='group'?'Группа':(active.username?'@'+esc(active.username):'личный чат')}</small></div><button class="icon" id="chatinfo">ⓘ</button></header><div id="messages" class="messages"></div><div class="picker hidden" id="picker"></div><form class="composer" id="composer"><button type="button" class="tool" id="emoji">😊</button><button type="button" class="tool" id="stickers">🧸</button><button type="button" class="tool" id="gifs">GIF</button><label class="tool">📎<input type="file" id="file" hidden></label><input id="msg" placeholder="Написать сообщение…" autocomplete="off"><button class="send">➤</button></form></section>`;$('#composer').onsubmit=sendMessage;$('#emoji').onclick=()=>openPicker('emoji');$('#stickers').onclick=()=>openPicker('stickers');$('#gifs').onclick=()=>openPicker('gifs');$('#file').onchange=uploadFile;$('#chatinfo').onclick=chatInfo;loadMessages();connectWS()}
async function loadMessages(){try{messages=await req(`/api/chats/${active.id}/messages`);drawMessages()}catch(e){toast(e.message)}}
function drawMessages(){const b=$('#messages');if(!b)return;b.innerHTML=messages.map(m=>{const mine=m.sender_id===me.id;let media=m.media_url?(m.media_type?.startsWith('image')||m.media_type==='sticker'||m.media_type==='gif'?`<img class="media" src="${esc(m.media_url)}">`:`<a class="file" href="${esc(m.media_url)}" target="_blank">📎 Файл</a>`):'';return`<article class="msg ${mine?'mine':''}" data-id="${m.id}"><div class="bubble">${m.deleted?'<i>Сообщение удалено</i>':(m.text?`<div>${esc(m.text)}</div>`:'')}${media}<footer>${t(m.created_at)} ${m.edited?'· изм.':''} ${m.pinned?'· 📌':''} <button class="mini" onclick="toggleFav(${m.id})">⭐</button></footer></div></article>`}).join('');b.scrollTop=b.scrollHeight;$$('.msg.mine',b).forEach(e=>e.oncontextmenu=x=>{x.preventDefault();messageMenu(+e.dataset.id)})}
async function sendMessage(e){e.preventDefault();const i=$('#msg'),text=i.value.trim();if(!text)return;i.value='';try{const m=await req(`/api/chats/${active.id}/messages`,{method:'POST',body:JSON.stringify({text})});if(!messages.some(x=>x.id===m.id))messages.push(m);drawMessages()}catch(e){toast(e.message)}}
async function toggleFav(id){try{const r=await req('/api/extras/favorites/'+id,{method:'POST'});toast(r.favorite?'Добавлено в избранное':'Удалено из избранного')}catch(e){toast(e.message)}}
async function uploadFile(e){const f=e.target.files[0];if(!f)return;try{const fd=new FormData();fd.append('file',f);const x=await req('/api/files/upload',{method:'POST',body:fd});const m=await req(`/api/chats/${active.id}/messages`,{method:'POST',body:JSON.stringify({media_url:x.url,media_type:x.content_type,text:f.name})});messages.push(m);drawMessages()}catch(e){toast(e.message)}e.target.value=''}
function openPicker(type){const p=$('#picker');p.classList.remove('hidden');p.innerHTML='<div class="pickerhead"><b>'+type.toUpperCase()+'</b><button onclick="$(\'#picker\').classList.add(\'hidden\')">×</button></div><div class="pickergrid" id="pickgrid">Загрузка…</div>';if(type==='emoji')req('/api/extras/emoji').then(x=>$('#pickgrid').innerHTML=x.items.map(e=>`<button onclick="putEmoji('${e}')">${e}</button>`).join(''));if(type==='stickers')req('/api/extras/stickers').then(x=>$('#pickgrid').innerHTML=x.items.map(e=>`<button class="sticker" onclick="putSticker('${e.emoji}')">${e.emoji}</button>`).join(''));if(type==='gifs'){ $('#pickgrid').innerHTML='<input id="gifq" placeholder="поиск GIF"><button class="primary" onclick="gifSearch()">Найти</button><div id="gifitems"></div>';gifSearch()}}
function putEmoji(e){$('#msg').value+=e;$('#msg').focus();$('#picker').classList.add('hidden')}
function putSticker(e){sendMediaEmoji(e,'sticker')}
async function sendMediaEmoji(e,type){$('#picker').classList.add('hidden');try{const m=await req(`/api/chats/${active.id}/messages`,{method:'POST',body:JSON.stringify({text:e,media_type:type})});messages.push(m);drawMessages()}catch(x){toast(x.message)}}
async function gifSearch(){const q=$('#gifq')?.value||'funny';const box=$('#gifitems');if(!box)return;try{const x=await req('/api/extras/gifs?q='+encodeURIComponent(q));box.innerHTML=x.items.map(g=>`<button class="gifitem" onclick="sendGif('${g.url}')"><img src="${g.url}"><span>${esc(g.title)}</span></button>`).join('')}catch(e){box.textContent=e.message}}
async function sendGif(url){try{const m=await req(`/api/chats/${active.id}/messages`,{method:'POST',body:JSON.stringify({media_url:url,media_type:'gif',text:'GIF'})});messages.push(m);drawMessages();$('#picker').classList.add('hidden')}catch(e){toast(e.message)}}
function messageMenu(id){const m=messages.find(x=>x.id===id);modal(`<h2>Сообщение</h2><button class="wide" onclick="toggleFav(${id});$('#modal').remove()">⭐ ${'Добавить/убрать из избранного'}</button><button class="wide" onclick="editMsg(${id});$('#modal').remove()">✏️ Изменить</button><button class="wide danger" onclick="deleteMsg(${id});$('#modal').remove()">🗑 Удалить</button>`)}
async function editMsg(id){const m=messages.find(x=>x.id===id);const x=prompt('Изменить сообщение',m?.text||'');if(x===null)return;try{const n=await req(`/api/chats/${active.id}/messages/${id}`,{method:'PATCH',body:JSON.stringify({text:x})});messages=messages.map(v=>v.id===id?n:v);drawMessages()}catch(e){toast(e.message)}}
async function deleteMsg(id){try{await req(`/api/chats/${active.id}/messages/${id}`,{method:'DELETE'});messages=messages.map(v=>v.id===id?{...v,deleted:true,text:''}:v);drawMessages()}catch(e){toast(e.message)}}
function profile(){modal(`<div class="profile-card"><div class="profile-avatar avatar">${avatar(me)}</div><h2>${esc(me.display_name)}</h2><div class="muted">@${esc(me.username)}</div>${me.public_code?`<div class="code">ID ${esc(me.public_code)}</div>`:''}<label>Имя</label><input id="pn" value="${esc(me.display_name)}"><label>О себе</label><textarea id="pb">${esc(me.bio||'')}</textarea><label>URL аватара</label><input id="pa" value="${esc(me.avatar||'')}" placeholder="https://..."><button class="primary wide" onclick="saveProfile()">Сохранить профиль</button><button class="wide" onclick="theme()">🌗 Переключить тему</button>${me.role==='owner'?'<button class="wide" onclick="ownerPanel()">👑 Панель владельца</button>':''}<button class="wide danger" onclick="logout()">Выйти</button></div>`)}
async function saveProfile(){try{me=await req('/api/users/me',{method:'PATCH',body:JSON.stringify({display_name:$('#pn').value,bio:$('#pb').value,avatar:$('#pa').value||null})});$('#modal').remove();render()}catch(e){toast(e.message)}}
function theme(){localStorage.setItem('fenix_theme',localStorage.getItem('fenix_theme')==='dark'?'light':'dark');$('#modal').remove();render()}
async function ownerPanel(){const us=await req('/api/users?limit=100');$('#modal')?.remove();modal(`<h2>👑 Владелец</h2><p class="muted">Выдача 3- или 4-значного ID пользователю.</p><select id="ou">${us.map(u=>`<option value="${u.id}">${esc(u.display_name)} @${esc(u.username)}</option>`).join('')}</select><input id="oc" maxlength="4" placeholder="123 или 1234"><button class="primary wide" onclick="issueCode()">Выдать ID</button><div id="ownerout"></div>`)}
async function issueCode(){try{const x=await req('/api/extras/owner/issue-code',{method:'POST',body:JSON.stringify({user_id:+$('#ou').value,code:$('#oc').value})});$('#ownerout').textContent='Выдан ID '+x.public_code;toast('ID выдан')}catch(e){toast(e.message)}}
async function chatInfo(){try{const ms=await req(`/api/chats/${active.id}/members`);modal(`<h2>${esc(active.title)}</h2><p>${esc(active.description||'')}</p><b>Участники: ${ms.length}</b>${ms.map(u=>`<div class="person"><div class="avatar">${avatar(u)}</div><div><b>${esc(u.display_name)}</b><small>@${esc(u.username)} ${u.public_code?'· ID '+u.public_code:''}</small></div></div>`).join('')}<button class="wide" onclick="$('#modal').remove()">Закрыть</button>`)}catch(e){toast(e.message)}}
function newChat(){mode='people';query='';loadList()}
function logout(){req('/api/auth/logout',{method:'POST'}).catch(()=>{});token='';me=null;localStorage.removeItem('fenix_token');if(ws)try{ws.close()}catch{}render()}
function connectWS(){if(ws)try{ws.close()}catch{};const proto=location.protocol==='https:'?'wss':'ws';ws=new WebSocket(`${proto}://${location.host}/ws/${active.id}?token=${encodeURIComponent(token)}`);ws.onmessage=e=>{try{const d=JSON.parse(e.data);if(d.type==='message'&&!messages.some(x=>x.id===d.message.id)){messages.push(d.message);drawMessages()}if(d.type==='message_updated'){messages=messages.map(x=>x.id===d.message.id?d.message:x);drawMessages()}if(d.type==='message_deleted'){messages=messages.map(x=>x.id===d.message_id?{...x,deleted:true,text:''}:x);drawMessages()}}catch{}}}
if(token)boot();else render();
